// WhatsApp entry buttons on /bots/ pages. Message contract: C:\DEV\bots\BOTS_ARCHITECTURE.md section 2. Generated by sites/bots-build.mjs.
// Every button is a real link without this script; the script only swaps in the number from the leads system (window.LBE_CLIENT.waNumber) and adds ?ref=.
(function () {
  var CFG = { number: "972554606831", giftUntil: "2026-12-31" };
  var C = window.LBE_CLIENT;
  var number = (C && C.waNumber) || CFG.number;
  var ref = (new URLSearchParams(location.search).get("ref") || "").replace(/[^A-Za-z0-9_-]/g, "").slice(0, 32);
  var LEAD = { demo: "אשמח לנסות הדגמה", order: "אני רוצה להזמין בוט", ask: "יש לי שאלה" };
  document.querySelectorAll("a[data-wa-code]").forEach(function (a) {
    var intent = a.getAttribute("data-wa-intent");
    var text = "היי, " + (LEAD[intent] || LEAD.demo) + ".\nקוד: " + a.getAttribute("data-wa-code") + "\nכוונה: " + intent + (ref ? "\nref: " + ref : "");
    a.href = "https://wa.me/" + number + "?text=" + encodeURIComponent(text);
  });
  if (ref) document.querySelectorAll("a[data-order]").forEach(function (a) { a.href += "?ref=" + ref; });
  // The gift disappears after the last day (Israel time).
  try {
    var today = new Intl.DateTimeFormat("en-CA", { timeZone: "Asia/Jerusalem" }).format(new Date());
    if (today > CFG.giftUntil) document.querySelectorAll(".gift[data-until]").forEach(function (g) { g.hidden = true; });
  } catch (e) {}
})();
